\label{thm:discrete}
For every discrete abelian group $D$,
\[
  |\mathcal C(D)|=\operatorname{width}\mathcal C(D)=
  \begin{cases}
    1,&D\text{ is finite},\\
    2^{2^{|D|}},&D\text{ is infinite}.
  \end{cases}
\]

\label{cor:basic-groups}
For every prime $p$ and every positive integer $m$,
\[
\begin{split}
  |\mathcal C(\mathbb Z^m)|=\operatorname{width}\mathcal C(\mathbb Z^m)&=2^{\mathfrak c},\\
  |\mathcal C(\mathbb Z(p^\infty)^m)|
    =\operatorname{width}\mathcal C(\mathbb Z(p^\infty)^m)&=2^{\mathfrak c}.
\end{split}
\]

We call the greatest element $t$ of a poset \emph{order-compact}
if, whenever a nonempty directed subset has supremum $t$, one
of its members equals $t$.

\label{lem:discrete-top-compact}
For every discrete abelian group $D$, the greatest element
$\delta$ of $\mathcal C(D)$ is order-compact.
